    74→typedef struct {
    75→  PyObject *type_decimal;
    76→} modulestate;
    77→
    78→static int module_traverse(PyObject *m, visitproc visit, void *arg);
    79→static int module_clear(PyObject *m);
    80→static void module_free(void *m);
    81→
    82→static struct PyModuleDef moduledef = {
    83→  PyModuleDef_HEAD_INIT,
    84→  "ujson",
    85→  0,                    /* m_doc */
    86→  sizeof(modulestate),  /* m_size */
    87→  ujsonMethods,         /* m_methods */
    88→  NULL,                 /* m_slots */
    89→  module_traverse,      /* m_traverse */
    90→  module_clear,         /* m_clear */
    91→  module_free           /* m_free */
    92→};
    93→
    94→#define modulestate(o) ((modulestate *)PyModule_GetState(o))
    95→#define modulestate_global modulestate(PyState_FindModule(&moduledef))
    96→
    97→#ifndef PYPY_VERSION
    98→/* Used in objToJSON.c */
    99→int object_is_decimal_type(PyObject *obj)
   100→{
   101→  PyObject *module = PyState_FindModule(&moduledef);
   102→  if (module == NULL) return 0;
   103→  modulestate *state = modulestate(module);
   104→  if (state == NULL) return 0;
   105→  PyObject *type_decimal = state->type_decimal;
   106→  if (type_decimal == NULL) {
   107→    PyErr_Clear();
   108→    return 0;
   109→  }
   110→  int result = PyObject_IsInstance(obj, type_decimal);
   111→  if (result == -1) {
   112→    PyErr_Clear();
   113→    return 0;
   114→  }
   115→  return result;
   116→}
   117→#else
   118→/* Used in objToJSON.c */
   119→int object_is_decimal_type(PyObject *obj)
   120→{
   121→  PyObject *module = PyImport_ImportModule("decimal");
   122→  if (module == NULL) {
   123→    PyErr_Clear();
   124→    return 0;
   125→  }
   126→  PyObject *type_decimal = PyObject_GetAttrString(module, "Decimal");
   127→  if (type_decimal == NULL) {
   128→    Py_DECREF(module);
   129→    PyErr_Clear();
   130→    return 0;
   131→  }
   132→  int result = PyObject_IsInstance(obj, type_decimal);
   133→  if (result == -1) {
   134→    Py_DECREF(module);
   135→    Py_DECREF(type_decimal);
   136→    PyErr_Clear();
   137→    return 0;
   138→  }
   139→  return result;
   140→}
   141→#endif
